from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # employee -> year -> total leave days used
        self._used: dict[str, dict[int, int]] = {}
        # employee -> list of (start, end) approved requests
        self._requests: dict[str, list[tuple[date, date]]] = {}

    def _count_leave_days(self, start: date, end: date) -> int:
        """Count leave days between start and end inclusive, skipping weekends and holidays."""
        count = 0
        current = start
        while current <= end:
            if current.weekday() < 5 and current not in self.holidays:
                count += 1
            current += timedelta(days=1)
        return count

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get(employee, {}).get(year, 0)
        return max(0, self.days_per_year - used)

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date cannot be before start date.")

        if (start - today).days < 3:
            raise ValueError("Leave must be requested at least 3 days in advance.")

        # Determine the number of days requested, split across years if needed
        year_counts: dict[int, int] = {}
        current = start
        while current <= end:
            if current.weekday() < 5 and current not in self.holidays:
                year_counts[current.year] = year_counts.get(current.year, 0) + 1
            current += timedelta(days=1)

        # Check remaining balance for each affected year
        for year, needed in year_counts.items():
            if self.remaining(employee, year) < needed:
                raise ValueError(
                    f"Insufficient leave balance for {employee} in {year}: "
                    f"needs {needed}, has {self.remaining(employee, year)}."
                )

        # Deduct days
        self._used.setdefault(employee, {})
        for year, needed in year_counts.items():
            self._used[employee][year] = self._used[employee].get(year, 0) + needed

        # Record the request
        self._requests.setdefault(employee, []).append((start, end))

        return sum(year_counts.values())
